<script setup lang="ts">
import { onMounted, ref, watch } from 'vue';
import AdminGenres from './AdminGenres.vue';
import AdminTitleEditor from './AdminTitleEditor.vue';
import AdminMedia from './AdminMedia.vue';
import AdminR2PickerModal from './AdminR2PickerModal.vue';
import { fetchGenres } from '@/entities/genre/genre.api';
import { adminSearchTitles, createTitle, uploadPhoto, type AdminTitleListItem } from '@/entities/admin/admin.api';
import { useUserStore } from '@/entities/user/user.store';
import type { Genre } from '@/shared/api/types';

const user = useUserStore();
const tab = ref<'titles' | 'genres' | 'media'>('titles');
const roleBusy = ref(false);

// ── Create title form ─────────────────────────────────────
const genres = ref<Genre[]>([]);
const form = ref({
  displayName: '',
  seasonNumber: 1,
  seasonLabel: '',
  description: '',
  posterUrl: '',
  originalReleaseDate: '',
  genreIds: [] as number[],
  episodesCount: '' as string,
  episodesOpen: false,
  visible: true,
});
const altNames = ref<{ kind: 'original' | 'english' | 'ukrainian' | 'other'; name: string }[]>([]);
const createError = ref<string | null>(null);
const createOk = ref(false);
const creating = ref(false);
const showCreate = ref(false);
const showPhotoPicker = ref(false);

function openPhotoPicker(): void {
  showPhotoPicker.value = true;
}

function selectPhoto(url: string): void {
  form.value.posterUrl = url;
  showPhotoPicker.value = false;
}

// Poster quick upload/paste state and methods
const posterUploading = ref(false);
const posterUploadError = ref<string | null>(null);
const posterFileInput = ref<HTMLInputElement | null>(null);

function triggerPosterUpload(): void {
  posterFileInput.value?.click();
}

async function handlePosterFile(file: File | Blob): Promise<void> {
  posterUploading.value = true;
  posterUploadError.value = null;
  try {
    const label = `Постер: ${form.value.displayName || 'Тайтл без назви'}`;
    const res = await uploadPhoto(file, label);
    form.value.posterUrl = res.url;
  } catch (e) {
    posterUploadError.value = e instanceof Error ? e.message : 'Помилка завантаження постеру';
  } finally {
    posterUploading.value = false;
  }
}

function onPosterFileSelect(e: Event): void {
  const input = e.target as HTMLInputElement;
  const f = input.files?.[0];
  if (f) void handlePosterFile(f);
}

function onPosterPaste(e: ClipboardEvent): void {
  const text = e.clipboardData?.getData('text/plain')?.trim() || '';
  if (/^https?:\/\//i.test(text) && (text.includes('/posters/') || text.includes('/photos/'))) {
    e.preventDefault();
    form.value.posterUrl = text;
    return;
  }
  const items = e.clipboardData?.items;
  if (!items) return;
  for (const item of items) {
    if (item.type.indexOf('image') !== -1) {
      const f = item.getAsFile();
      if (f) {
        e.preventDefault();
        void handlePosterFile(f);
        break;
      }
    }
  }
}

// ── Search / select ──────────────────────────────────────
const query = ref('');
const results = ref<AdminTitleListItem[]>([]);
const selectedId = ref<number | null>(null);

function toggleGenre(id: number): void {
  const i = form.value.genreIds.indexOf(id);
  if (i >= 0) form.value.genreIds.splice(i, 1);
  else form.value.genreIds.push(id);
}

function addAltName(): void {
  altNames.value.push({ kind: 'original', name: '' });
}

function removeAltName(i: number): void {
  altNames.value.splice(i, 1);
}

async function submitCreate(): Promise<void> {
  createError.value = null;
  createOk.value = false;
  if (!String(form.value.displayName).trim()) {
    createError.value = 'Вкажіть назву для відображення';
    return;
  }
  creating.value = true;
  try {
    const countRaw = String(form.value.episodesCount).trim();
    const res = await createTitle({
      displayName: String(form.value.displayName).trim(),
      names: altNames.value.filter((n) => String(n.name).trim()).map((n) => ({ kind: n.kind, name: String(n.name).trim() })),
      description: String(form.value.description).trim(),
      posterUrl: String(form.value.posterUrl).trim() || null,
      originalReleaseDate: form.value.originalReleaseDate || null,
      genreIds: form.value.genreIds,
      seasonNumber: Number(form.value.seasonNumber) || 1,
      seasonLabel: String(form.value.seasonLabel).trim() || null,
      status: form.value.visible ? 'ongoing' : 'hidden',
      episodesPlanned: countRaw
        ? { count: Number(countRaw), open: form.value.episodesOpen }
        : { count: null, open: false },
    });
    createOk.value = true;
    selectedId.value = res.id;
    // reset the essentials
    form.value.displayName = '';
    form.value.description = '';
    form.value.posterUrl = '';
    form.value.seasonNumber = 1;
    form.value.seasonLabel = '';
    form.value.genreIds = [];
    form.value.originalReleaseDate = '';
    form.value.episodesCount = '';
    form.value.episodesOpen = false;
    form.value.visible = true;
    altNames.value = [];
    showCreate.value = false;
    await search();
  } catch (e) {
    createError.value = e instanceof Error ? e.message : 'Помилка створення';
  } finally {
    creating.value = false;
  }
}

async function search(): Promise<void> {
  results.value = await adminSearchTitles(query.value.trim()).catch(() => []);
}

async function refreshRole(): Promise<void> {
  roleBusy.value = true;
  await user.refreshAdmin();
  roleBusy.value = false;
}

onMounted(async () => {
  genres.value = await fetchGenres().catch(() => []);
  // The role may still be resolving on a direct page load; check now and refresh
  // once if unknown, then load the title list when confirmed admin.
  if (!user.isAdmin()) await user.refreshAdmin();
  if (user.isAdmin()) await search();
});

// Load titles as soon as the admin role is confirmed (handles the ready race).
watch(
  () => user.isAdmin(),
  (isAdmin) => {
    if (isAdmin && results.value.length === 0) void search();
  },
);
</script>

<template>
  <div class="admin">
    <!-- No access -->
    <div v-if="!user.isAdmin()" class="admin__denied">
      <h1>Немає доступу</h1>
      <p>Ваш акаунт не визначено як адміністратор. Переконайтесь, що ви є в приватній групі з тегом,
        і оновіть роль.</p>
      <button class="btn" type="button" :disabled="roleBusy" @click="refreshRole">
        {{ roleBusy ? 'Перевірка…' : 'Перевірити роль знову' }}
      </button>
      <RouterLink class="admin__home" to="/">На головну</RouterLink>
    </div>

    <template v-else>
      <div class="admin__tabs">
        <button :class="{ on: tab === 'titles' }" @click="tab = 'titles'">Тайтли</button>
        <button :class="{ on: tab === 'genres' }" @click="tab = 'genres'">Жанри</button>
        <button :class="{ on: tab === 'media' }" @click="tab = 'media'">Сховище R2</button>
      </div>

      <!-- Titles -->
      <div v-if="tab === 'titles'">
        <div class="admin__section">
          <button class="btn btn--wide" type="button" @click="showCreate = true">
            + Створити тайтл
          </button>

          <!-- Create Title Modal -->
          <div v-if="showCreate" class="modal-backdrop" @click.self="showCreate = false">
            <div class="modal-content">
              <header class="modal-header">
                <h3>Створити тайтл</h3>
                <button type="button" class="modal-close" @click="showCreate = false">✕</button>
              </header>
              <form class="modal-body form" @submit.prevent="submitCreate">
                <label class="field">
                  <span>Назва для відображення *</span>
                  <input v-model="form.displayName" placeholder="Напр. Наруто" />
                </label>
                <div class="row">
                  <label class="field">
                    <span>Сезон (номер)</span>
                    <input v-model="form.seasonNumber" type="number" />
                  </label>
                  <label class="field">
                    <span>Назва сезону (напр. Фільм, OVA)</span>
                    <input v-model="form.seasonLabel" placeholder="Сезон 1" />
                  </label>
                </div>
                <div class="row">
                  <label class="field">
                    <span>Дата оригіналу</span>
                    <input v-model="form.originalReleaseDate" type="date" />
                  </label>
                  <label class="field">
                    <span>К-сть серій (порожньо = N/A)</span>
                    <input v-model="form.episodesCount" type="number" />
                  </label>
                </div>
                <label class="field">
                  <span>Посилання на постер (t.me/… або пряме посилання)</span>
                  <div class="input-with-upload">
                    <input v-model="form.posterUrl" placeholder="https://t.me/DaliBudeDub/13" @paste="onPosterPaste" />
                    <button class="btn btn--upload" type="button" :disabled="posterUploading" @click="triggerPosterUpload">
                      {{ posterUploading ? '☁ Завантаження…' : '☁ Завантажити / Вставити' }}
                    </button>
                    <button class="btn btn--upload" type="button" @click="openPhotoPicker">
                      📁 Обрати з R2
                    </button>
                    <input ref="posterFileInput" type="file" accept="image/*" class="hidden-file-input" @change="onPosterFileSelect" />
                  </div>
                  <p v-if="posterUploadError" class="err">{{ posterUploadError }}</p>
                </label>
                <label class="field">
                  <span>Опис</span>
                  <textarea v-model="form.description" rows="3" />
                </label>
                <label class="check">
                  <input v-model="form.episodesOpen" type="checkbox" /> «+» (із запасом)
                </label>
                <label class="check">
                  <input v-model="form.visible" type="checkbox" /> Видне користувачам
                </label>

                <div class="subblock">
                  <div class="subblock__head">
                    <span>Альтернативні назви</span>
                    <button type="button" class="btn btn--ghost btn--sm" @click="addAltName">
                      + Додати
                    </button>
                  </div>
                  <div v-for="(n, i) in altNames" :key="i" class="altrow">
                    <select v-model="n.kind">
                      <option value="original">Оригінал</option>
                      <option value="english">Англ.</option>
                      <option value="ukrainian">Укр.</option>
                      <option value="other">Інша</option>
                    </select>
                    <input v-model="n.name" placeholder="Назва" />
                    <button type="button" class="btn--del" title="Видалити" @click="removeAltName(i)">
                      ✕
                    </button>
                  </div>
                </div>

                <div class="subblock">
                  <span class="subblock__label">Жанри</span>
                  <div class="genres-pick">
                    <button
                      v-for="g in genres"
                      :key="g.id"
                      type="button"
                      class="chip"
                      :class="{ on: form.genreIds.includes(g.id) }"
                      @click="toggleGenre(g.id)"
                    >
                      {{ g.name }}
                    </button>
                  </div>
                </div>

                <p v-if="createError" class="err">{{ createError }}</p>
                <p v-if="createOk" class="ok">✅ Тайтл створено</p>
                <button class="btn" type="submit" :disabled="creating">Створити</button>
              </form>
            </div>
          </div>
          <AdminR2PickerModal
            v-if="showPhotoPicker"
            type="photo"
            @select="selectPhoto"
            @close="showPhotoPicker = false"
          />
        </div>

        <div class="admin__section">
          <input v-model="query" class="search" placeholder="Пошук тайтлів для редагування…" @input="search" />
          <ul class="tlist">
            <li
              v-for="t in results"
              :key="t.id"
              :class="{ on: selectedId === t.id }"
              @click="selectedId = t.id"
            >
              <span>{{ t.displayName }}</span>
              <span class="mono">{{ t.seasonLabel || 'с.' + t.seasonNumber }}</span>
            </li>
          </ul>
        </div>

        <!-- Edit Title Modal -->
        <div v-if="selectedId" class="modal-backdrop" @click.self="selectedId = null">
          <div class="modal-content modal-content--wide animate-scale">
            <header class="modal-header">
              <h3>Керування тайтлом</h3>
              <button type="button" class="modal-close" @click="selectedId = null">✕</button>
            </header>
            <div class="modal-body no-padding">
              <AdminTitleEditor :key="selectedId" :title-id="selectedId" @close="selectedId = null" />
            </div>
          </div>
        </div>
      </div>

      <!-- Genres -->
      <AdminGenres v-else-if="tab === 'genres'" />

      <!-- R2 storage manager -->
      <AdminMedia v-else-if="tab === 'media'" />
    </template>
  </div>
</template>

