<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import {
  listMedia,
  listPhotos,
  type MediaAsset,
  type PhotoAsset,
} from '@/entities/admin/admin.api';

const props = defineProps<{
  type: 'video' | 'photo';
}>();

const emit = defineEmits<{
  (e: 'select', value: string): void;
  (e: 'close'): void;
}>();

const loading = ref(true);
const error = ref<string | null>(null);
const searchQuery = ref('');

const videos = ref<MediaAsset[]>([]);
const photos = ref<PhotoAsset[]>([]);

async function load(): Promise<void> {
  loading.value = true;
  error.value = null;
  try {
    if (props.type === 'video') {
      videos.value = await listMedia();
    } else {
      photos.value = await listPhotos();
    }
  } catch (e) {
    error.value = e instanceof Error ? e.message : 'Не вдалося завантажити ресурси';
  } finally {
    loading.value = false;
  }
}

const filteredVideos = computed(() => {
  const q = searchQuery.value.trim().toLowerCase();
  if (!q) return videos.value;
  return videos.value.filter(
    (v) =>
      (v.label && v.label.toLowerCase().includes(q)) ||
      v.id.toLowerCase().includes(q),
  );
});

const filteredPhotos = computed(() => {
  const q = searchQuery.value.trim().toLowerCase();
  if (!q) return photos.value;
  return photos.value.filter(
    (p) =>
      (p.label && p.label.toLowerCase().includes(q)) ||
      p.url.toLowerCase().includes(q),
  );
});

function selectVideo(v: MediaAsset): void {
  emit('select', v.id);
}

function selectPhoto(p: PhotoAsset): void {
  emit('select', p.url);
}

function fmtDuration(sec: number | null): string {
  if (sec == null) return '0:00';
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${s < 10 ? '0' : ''}${s}`;
}

onMounted(load);
</script>

<template>
  <div class="modal-backdrop" @click.self="emit('close')">
    <div class="modal-content r2-picker">
      <header class="modal-header">
        <h3>Оберіть {{ type === 'video' ? 'відео HLS' : 'зображення' }} з R2</h3>
        <button type="button" class="modal-close" @click="emit('close')">✕</button>
      </header>

      <div class="modal-body picker-body">
        <input
          v-model="searchQuery"
          class="picker-search"
          :placeholder="type === 'video' ? 'Пошук за підказкою або UUID…' : 'Пошук за описом або URL…'"
        />

        <div v-if="loading" class="picker-loading">Завантаження…</div>
        <div v-else-if="error" class="msg msg--err">{{ error }}</div>
        
        <div v-else class="picker-results no-scrollbar">
          <!-- Video list -->
          <template v-if="type === 'video'">
            <p v-if="filteredVideos.length === 0" class="picker-empty">Нічого не знайдено.</p>
            <div
              v-for="v in filteredVideos"
              :key="v.id"
              class="picker-item picker-item--video"
              @click="selectVideo(v)"
            >
              <div class="picker-item__main">
                <span class="picker-item__label">{{ v.label || 'Відео без підказки' }}</span>
                <code class="picker-item__uuid">{{ v.id }}</code>
              </div>
              <div class="picker-item__meta">
                <span>{{ v.segmentCount }} сегм.</span>
                <span>· {{ fmtDuration(v.durationS) }}</span>
              </div>
            </div>
          </template>

          <!-- Photo grid -->
          <template v-else>
            <p v-if="filteredPhotos.length === 0" class="picker-empty">Нічого не знайдено.</p>
            <div class="photo-grid">
              <div
                v-for="p in filteredPhotos"
                :key="p.id"
                class="picker-item picker-item--photo"
                @click="selectPhoto(p)"
              >
                <div class="picker-item__img-box">
                  <img :src="p.url" alt="Мініатюра" loading="lazy" />
                </div>
                <span class="picker-item__photo-label" :title="p.label || 'Без опису'">
                  {{ p.label || 'Без опису' }}
                </span>
              </div>
            </div>
          </template>
        </div>
      </div>
    </div>
  </div>
</template>

